// Do the generated REST request builders produce the requests the API expects?
//
// HaivenRestApi.h is generated by codegen/emit_rest.py and, like the protocol
// and session cores, carries no engine types, so the whole of it is under an
// ordinary compiler here. What this pins is the request each builder hands a
// transport: method, encoded path and query, body, content type, and whether
// the operation is a browser navigation rather than a request.
#include "HaivenRestApi.h"
#include <iostream>
#include <string>
#include <vector>

namespace
{
	std::vector<std::string> Failures;

	void Check(const char* What, bool Condition)
	{
		if (!Condition)
		{
			Failures.emplace_back(What);
		}
	}
}

int main()
{
	using namespace Haiven::Rest;

	const FRestRequest Entitlements = GetUsersMeEntitlements();
	Check("the entitlement read is a GET", Entitlements.Method == "GET");
	Check("of the account entitlements path", Entitlements.Path == "/users/me/entitlements");
	Check("without a body", Entitlements.Body.empty() && Entitlements.ContentType.empty());
	Check("naming the schema it answers with", Entitlements.ResponseSchema == "AccountEntitlementsResponse");
	Check("and is sent, not navigated", !Entitlements.bNavigation);

	const FRestRequest LegacyMessages = GetChatChannelsChannelIdMessages("chan/1 x", std::nullopt, std::string("thread"));
	Check("the pre-cursor positional call still binds its third argument to parentMessageId",
		LegacyMessages.Path == "/chat/channels/chan%2F1%20x/messages?parentMessageId=thread");
	const FRestRequest Messages = GetChatChannelsChannelIdMessages("chan/1 x", std::string("m&2"), std::nullopt, 25, std::string("m-after"));
	Check("path parameters are percent-encoded",
		Messages.Path == "/chat/channels/chan%2F1%20x/messages?beforeMessageId=m%262&afterMessageId=m-after&limit=25");

	const FRestRequest Apps = GetApps(std::nullopt, std::vector<std::string>{"rpg", "co op"}, std::nullopt, true);
	Check("array queries repeat and booleans are lower case", Apps.Path == "/apps?tag=rpg&tag=co%20op&earlyAccess=true");

	const std::string LoginJson = R"({"username":"player","password":"pw"})";
	const FRestRequest Login = PostAuthLogin(LoginJson);
	Check("JSON bodies are declared as JSON", Login.Method == "POST" && Login.ContentType == "application/json");
	Check("and carried unchanged", Login.Body == LoginJson);

	const FRestRequest Exchange = PostAuthHandoffExchange("code=c");
	Check("the handoff exchange is declared as a form", Exchange.ContentType == "application/x-www-form-urlencoded");

	const FRestRequest Sso = GetAuthSsoProviderUrl("google", "challenge", "S256");
	Check("SSO initiation is a navigation",
		Sso.bNavigation && Sso.Path == "/auth/sso/google?code_challenge=challenge&code_challenge_method=S256");
	Check("and so is the OAuth callback",
		GetAuthCallbackUrl("code", "st ate").Path == "/auth/callback?code=code&state=st%20ate");

	if (Failures.empty())
	{
		std::cout << "ok   C++ generated REST request builders" << std::endl;
		return 0;
	}

	for (const std::string& Failure : Failures)
	{
		std::cout << "FAIL " << Failure << std::endl;
	}

	return 1;
}
